[{"order":1,"type":"heading","text":"Implementing CORS and Security Headers (Helmet) in Express.js"},{"order":2,"type":"paragraph","text":"Securing your Express.js application is a critical step in production deployment. Two fundamental pillars of web security are Cross-Origin Resource Sharing (CORS) configuration and HTTP security headers. This tutorial demonstrates how to implement CORS using the cors middleware and secure your HTTP headers using Helmet."},{"order":3,"type":"subheading","text":"Prerequisites and Installation"},{"order":4,"type":"paragraph","text":"Before starting, ensure you have Node.js and Express installed. Install the required packages via npm:"},{"order":5,"type":"code","text":"npm install express cors helmet"},{"order":6,"type":"subheading","text":"Step 1: Setting up Express and Helmet"},{"order":7,"type":"paragraph","text":"Helmet is an Express middleware that sets various HTTP headers to help secure your app. It helps secure your application by setting headers such as Content-Security-Policy, X-Frame-Options, and X-Content-Type-Options."},{"order":8,"type":"code","text":"const express = require('express');
const helmet = require('helmet');

const app = express();

// Apply Helmet with default configurations
app.use(helmet());

app.get('/', (req, res) => {
  res.send('Secure Express Server');
});"},{"order":9,"type":"subheading","text":"Step 2: Configuring CORS"},{"order":10,"type":"paragraph","text":"CORS (Cross-Origin Resource Sharing) is a mechanism that allows restricted resources on a web page to be requested from another domain outside the domain from which the first resource was served. You can configure it globally or restrict it to specific origins."},{"order":11,"type":"code","text":"const cors = require('cors');

// Option 1: Enable CORS for all routes and origins
// app.use(cors());

// Option 2: Configure CORS for specific origins
const corsOptions = {
  origin: 'https://example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));"},{"order":12,"type":"subheading","text":"Step 3: Complete Integration Example"},{"order":13,"type":"paragraph","text":"Combine both middlewares in your main server file (e.g., server.js) to ensure proper security posture before defining your routes."},{"order":14,"type":"code","text":"const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 3000;

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
const whitelist = ['https://myfrontend.com', 'https://admin.myfrontend.com'];
const corsOptions = {
  origin: function (origin, callback) {
    if (whitelist.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  }
};
app.use(cors(corsOptions));

// Body parser
app.use(express.json());

// Routes
app.get('/api/data', (req, res) => {
  res.json({ message: 'This is secure data!' });
});

app.listen(PORT, () => {
  console.log('Server running on port ' + PORT);
});"},{"order":15,"type":"subheading","text":"Summary of Best Practices"},{"order":16,"type":"bullet_point","text":"Always place Helmet early in your middleware stack so headers are set correctly on all responses."},{"order":17,"type":"bullet_point","text":"Avoid using app.use(cors()) in production without a whitelist, as it opens your API to requests from any domain."},{"order":18,"type":"bullet_point","text":"Customize Helmet directives (like Content Security Policy) if your application loads external scripts, styles, or images."}]
